#!/usr/bin/env bash\nset -e\n\n# Mock `uptime` to return a fixed string\nTMPDIR=$(mktemp -d)\ncat > "$TMPDIR/uptime" <<'EOF'\n#!/usr/bin/env bash\necho "up 2 days, 3 hours, 4 minutes"\nEOF\nchmod +x "$TMPDIR/uptime"\nexport PATH="$TMPDIR:$PATH"\n\n# Source the utility and invoke main\nSCRIPT_DIR=$(cd "$(dirname \"${BASH_SOURCE[0]}\")/../src" && pwd)\noutput=$(bash "$SCRIPT_DIR/uptime-emoji.sh")\n\n# Verify that each expected emoji appears in the output\nif [[ "$output" != *"🌞"* ]] || [[ "$output" != *"⏰"* ]] || [[ "$output" != *"🕒"* ]]; then\n  echo "Test failed: missing expected emojis"\n  echo "Output was: $output"\n  exit 1\nfi\n\n# Ensure the textual units are present\nif [[ "$output" != *"2 days"* ]] || [[ "$output" != *"3 hours"* ]] || [[ "$output" != *"4 minutes"* ]]; then\n  echo "Test failed: missing time unit text"\n  exit 1\nfi\n\necho "Test passed: full uptime with emojis"\n
